def apply(inputs, premises):
    n = min(len(inputs["item_lengths"]), len(inputs["item_widths"]), len(inputs["item_heights"]), len(inputs["item_weights"]), len(inputs["item_personal_candidates"]), len(inputs["item_carryon_candidates"]))
    personal_used = 0
    carryon_used = 0
    checked_count = 0
    total = inputs["ticket_price"]
    for i in range(n):
        personal_fit = inputs["item_personal_candidates"][i] and inputs["item_lengths"][i] <= inputs["personal_item_limits"][0] and inputs["item_widths"][i] <= inputs["personal_item_limits"][1] and inputs["item_heights"][i] <= inputs["personal_item_limits"][2]
        carryon_fit = inputs["item_carryon_candidates"][i] and inputs["item_lengths"][i] <= inputs["carryon_limits"][0] and inputs["item_widths"][i] <= inputs["carryon_limits"][1] and inputs["item_heights"][i] <= inputs["carryon_limits"][2]
        free_item = False
        if personal_fit and personal_used < inputs["personal_item_allowance"]:
            personal_used = personal_used + 1
            free_item = True
        elif carryon_fit and carryon_used < inputs["carryon_allowance"]:
            carryon_used = carryon_used + 1
            free_item = True
        if not free_item:
            checked_count = checked_count + 1
            ordinal = checked_count - 1
            base_index = min(ordinal, len(inputs["base_checked_fees"]) - 1)
            weight_limit_index = min(ordinal, len(inputs["checked_standard_weight_limits"]) - 1)
            base_fee = inputs["base_checked_fees"][base_index]
            overweight_fee = 0
            if inputs["item_weights"][i] > inputs["checked_standard_weight_limits"][weight_limit_index]:
                for j in range(min(len(inputs["overweight_lower_bounds"]), len(inputs["overweight_upper_bounds"]), len(inputs["overweight_fees"]))):
                    if inputs["item_weights"][i] > inputs["overweight_lower_bounds"][j] and inputs["item_weights"][i] <= inputs["overweight_upper_bounds"][j]:
                        overweight_fee = inputs["overweight_fees"][j]
                        break
            linear_size = inputs["item_lengths"][i] + inputs["item_widths"][i] + inputs["item_heights"][i]
            oversize_fee = 0
            if linear_size > inputs["checked_standard_linear_size"]:
                for j in range(min(len(inputs["oversize_lower_bounds"]), len(inputs["oversize_upper_bounds"]), len(inputs["oversize_fees"]))):
                    if linear_size > inputs["oversize_lower_bounds"][j] and linear_size <= inputs["oversize_upper_bounds"][j]:
                        oversize_fee = inputs["oversize_fees"][j]
                        break
            total = total + base_fee + max(overweight_fee, oversize_fee)
    return {"answer": int(round(total))}

def apply(inputs, premises):
    count = min(len(inputs["bracket_subsections"]), len(inputs["bracket_upper_bounds"]), len(inputs["bracket_base_amounts"]), len(inputs["bracket_excess_floors"]), len(inputs["bracket_rates"]))
    applicable = -1
    for i in range(count):
        if inputs["bracket_upper_bounds"][i] < 0 or inputs["taxable_income"] <= inputs["bracket_upper_bounds"][i]:
            applicable = i
            break
    answer = "Contradiction"
    if applicable >= 0:
        expected_tax = inputs["bracket_base_amounts"][applicable] + inputs["bracket_rates"][applicable] * (inputs["taxable_income"] - inputs["bracket_excess_floors"][applicable])
        if inputs["claimed_subsection"] == inputs["bracket_subsections"][applicable] and abs(inputs["claimed_tax_amount"] - expected_tax) < 0.005:
            answer = "Entailment"
    return {"answer": answer}

